        SELECT 'ORD' || LPAD(ORDER_SEQ.NEXTVAL, 10, '0')
        FROM DUAL

	INSERT
	  INTO TBL_ORDER
	(
	  ORDER_NO
	, MEMBER_ID
	, ORDER_DATE
	, RCVR_NAME
	, RCVR_PHONE
	, RCVR_ADDRESS
	, DLVR_REQ_MSG
	, DLVR_STATUS
	)
	VALUES
	(
	  #{ orderNo }
	, #{ memberId }
	, SYSDATE
	, #{ rcvrName }
	, #{ rcvrPhone }
	, #{ rcvrAddress }
	, #{ dlvrReqMsg }
	, #{ dlvrStatus }
	)


        SELECT ORDER_ITEM_SEQ.NEXTVAL FROM DUAL

	INSERT
	  INTO TBL_ORDER_ITEM
	(
	  ORDER_ITEM_NO
	, ORDER_NO
	, OPT_COMB_NO
	, ORDER_QUANTITY
	, ORDER_AMOUNT
	)
	VALUES
	(
	  #{ orderItemNo }
	, #{ orderNo }
	, #{ optCombNo }
	, #{ orderQuantity }
	, #{ orderAmount }
	)

INSERT
  INTO TBL_DELIVERY
(
  ORDER_NO
, DELIVERY_FEE
, DELIVERY_COMPANY
, DISPATCH_DATE
, DELIVERY_DATE
)
VALUES
(
  #{ orderNo }
, #{ deliveryFee }
, #{ deliveryCompany }

, #{ dispatchDate }
, #{ deliveryDate }


, NULL
, NULL

)


         SELECT 'PAY' || LPAD(PAYMENT_SEQ.NEXTVAL, 10, '0')
           FROM DUAL

	INSERT
	  INTO TBL_PAYMENT
	(
	  PAYMENT_NO
	, ORDER_NO
	, PAYMENT_METHOD
	, PAYMENT_AMOUNT
	, PAYMENT_DATETIME
	)
	VALUES
	(
	  #{ paymentNo }
	, #{ orderNo }
	, #{ paymentMethod }
	, #{ paymentAmount }
	, SYSDATE
	)

mapper.update:
UPDATE
	   TBL_STOCK
   SET STOCK_QTY = STOCK_QTY - #{ orderQuantity }
WHERE STOCK_NO = (SELECT STOCK_NO
							    FROM (
							        SELECT A.STOCK_NO
							        FROM TBL_STOCK A
							        JOIN TBL_OPTION_COMB B ON A.STOCK_NO = B.STOCK_NO
							        WHERE B.OPT_COMB_NO = #{optCombNo}
							          AND A.STOCK_QTY >= #{orderQuantity}
							        ORDER BY A.INS_DT
							    ) 
							    WHERE ROWNUM = 1
							)
